import React, { useState } from "react";
import Navbar from "./components/Navbar";
import HeroSlider from "./components/HeroSlider";
import BestProducts from "./components/BestProducts";
import Assurance from "./components/Assurance";
import Footer from "./components/Footer";

export default function Home() {
  // State to control which section is visible
  const [activeSection, setActiveSection] = useState("home"); // default section

  return (
    <div>
      {/* Pass setActiveSection function to Navbar */}
      <Navbar setActiveSection={setActiveSection} />

      {/* Render sections based on state */}
      {activeSection === "home" && <HeroSlider />}
      {activeSection === "products" && <BestProducts />}
      {activeSection === "assurance" && <Assurance />}

      <Footer />
    </div>
  );
}
